// Standalone Eigen regression/property test. Define SEED_NATIVE_EXTRACTED to
// additionally exercise the exact transformed KinoAstar functions generated by
// the root verifier (including the byte-unchanged native getFlatState).
#include "seed_parameterization.hpp"
#include <cassert>
#include <iostream>
#include <numeric>
#ifdef SEED_NATIVE_EXTRACTED
#define ROS_ERROR(...) ((void)0)
#include "native_functions.hpp"
#include "native_fixture.hpp"
#endif

namespace sp=seed_parameterization;
struct Flat {
  std::vector<Eigen::Vector3d> traj_pts;
  std::vector<double> thetas;
  Eigen::MatrixXd start_state,final_state;
  int singul=0;
};
void flatState(const Eigen::Vector4d& q,const Eigen::Vector2d&,int gear,Eigen::MatrixXd& state) {
  state=Eigen::MatrixXd::Zero(2,3);state.col(0)=q.head<2>();
  state.col(1)=gear*std::max(.05,q[3])*Eigen::Vector2d(std::cos(q[2]),std::sin(q[2]));
}
std::vector<Eigen::Vector3d> straight(const Eigen::Vector3d& q,const std::vector<double>& offsets) {
  std::vector<Eigen::Vector3d> out;
  for(double s:offsets)out.emplace_back(q[0]+s*std::cos(q[2]),q[1]+s*std::sin(q[2]),q[2]);
  return out;
}
sp::Output<Flat> build(const std::vector<Eigen::Vector3d>& points,double speed=.05) {
  return sp::build<Flat>(points,speed,.05,Eigen::Vector2d::Zero(),.05,.1,1.,1.,.1,.4,flatState);
}
void validOutput(const sp::Output<Flat>& out,std::size_t blocks) {
  assert(out.valid&&out.flats.size()==blocks&&out.lengths.size()==blocks&&out.times.size()==blocks);
  assert(out.indices.size()==blocks+1&&out.gears.size()==blocks&&out.total>0.);
  double total=0.;
  for(std::size_t i=0;i<blocks;++i) {
    const auto& f=out.flats[i];assert(f.start_state.allFinite()&&f.final_state.allFinite());
    assert(f.singul==out.gears[i]&&(f.singul==1||f.singul==-1));
    assert(out.lengths[i]>0.&&out.times[i]>0.&&out.indices[i+1]>out.indices[i]);
    assert(f.traj_pts.size()==f.thetas.size()&&!f.traj_pts.empty());
    double t=0.;for(const auto& p:f.traj_pts){assert(p.allFinite()&&p[2]>0.);t+=p[2];}
    for(double yaw:f.thetas)assert(std::isfinite(yaw));
    assert(std::abs(t-out.times[i])<1e-11);
    const auto& end=out.path[out.indices[i+1]];
    assert((f.traj_pts.back().head<2>()-end.head<2>()).norm()<1e-12);
    total+=t;
  }
  assert(std::abs(total-out.total)<1e-11);
}
void failedOutput(const sp::Output<Flat>& out) {
  assert(!out.valid&&out.flats.empty()&&out.path.empty()&&out.lengths.empty()&&out.times.empty());
  assert(out.indices.empty()&&out.gears.empty()&&out.total==0.);
}

int main() {
  ::setenv("SEED_PARAMETERIZATION_FIX","1",1);
  const double nan=std::numeric_limits<double>::quiet_NaN();
  // Forward/reverse at origin, translated and rotated: distance and timing are
  // rigid-transform invariant, with no rank-deficient origin-based QR solve.
  for(double yaw:{0.,.1,1.3,3.141592653589793,-2.8})
    for(const Eigen::Vector2d shift:{Eigen::Vector2d(0.,0.),Eigen::Vector2d(4.,-7.),Eigen::Vector2d(91.,21.)})
      for(int direction:{-1,1}) {
        const auto path=straight({shift[0],shift[1],yaw},{0.,direction*.01,direction*.02});
        const auto out=build(path);validOutput(out,1);
        assert(out.gears[0]==direction&&std::abs(out.lengths[0]-.02)<1e-11);
        const double a=sp::distance(path[0].head<2>(),path[1].head<2>(),yaw,yaw,.1,.4);
        assert(std::abs(a-.01)<1e-11);
      }
  const Eigen::Vector2d p(.4,-.8),q(.42,-.79);
  const double reference=sp::distance(p,q,.2,.4,.1,.4);
  for(double yaw:{-.7,0.,1.7}) {
    Eigen::Rotation2Dd r(yaw);Eigen::Vector2d shift(2.,-4.);
    assert(std::abs(reference-sp::distance(r*p+shift,r*q+shift,.2+yaw,.4+yaw,.1,.4))<1e-12);
  }
  assert(sp::distance({0.,0.},{0.,.01},0.,0.,1.,.4)>0.);
  assert(std::isnan(sp::distance({0.,0.},{0.,0.},0.,.4,.1,.4)));
  assert(sp::distance({0.,0.},{0.,0.},0.,0.,.1,.4)==0.);
  assert(std::isnan(sp::distance({nan,0.},{1.,0.},0.,0.,.1,.4)));
  // Ordinary circular arcs retain the chord branch. Explicitly straddle the
  // turning-radius threshold, and expose the intentional metric lower bound.
  {
    const double angle=.2;
    const auto endpoint=[angle](double radius) {
      return Eigen::Vector2d(radius*std::sin(angle),radius*(1.-std::cos(angle)));
    };
    const auto ordinary=endpoint(.3);
    assert(std::abs(sp::distance({0.,0.},ordinary,0.,angle,.1,.4)-ordinary.norm())<1e-13);
    const auto above=endpoint(.1*(1.+1e-6)),below=endpoint(.1*(1.-1e-6));
    assert(std::abs(sp::distance({0.,0.},above,0.,angle,.1,.4)-above.norm())<1e-12);
    assert(std::abs(sp::distance({0.,0.},below,0.,angle,.1,.4)-.4*angle)<1e-12);
    const auto underweighted=endpoint(.05);
    assert(.001*angle<underweighted.norm());
    assert(std::abs(sp::distance({0.,0.},underweighted,0.,angle,.1,.001)-underweighted.norm())<1e-13);
  }
  // Shared acceleration must produce a continuous monotone profile, correct
  // endpoint arc and endpoint speed. Old Duration(.7A)/Length(A) fails this.
  for(double length:{.0001,.01,.2,2.,5.})for(double v0:{0.,.05,.3})for(double v1:{0.,.05,.3}) {
    const auto profile=sp::profile(length,v0,v1,1.,1.);
    if(!profile.valid){assert(length<std::abs(v1*v1-v0*v0)/(2.*.7));continue;}
    const double t=profile.duration;
    assert(sp::lengthAt(0.,length,t,v0,v1,1.,1.)==0.);
    assert(sp::lengthAt(t,length,t,v0,v1,1.,1.)==length);
    double previous=0.;
    for(int i=1;i<=1000;++i) {
      const double arc=sp::lengthAt(t*i/1000.,length,t,v0,v1,1.,1.);
      assert(std::isfinite(arc)&&arc>=previous-1e-13&&arc<=length+1e-13);previous=arc;
    }
    const double epsilon=std::min(1e-7,t*1e-5);
    assert(std::abs(sp::lengthAt(epsilon,length,t,v0,v1,1.,1.)/epsilon-v0)<1e-5);
    assert(std::abs((length-sp::lengthAt(t-epsilon,length,t,v0,v1,1.,1.))/epsilon-v1)<1e-5);
  }
  assert(std::isnan(sp::duration(0.,0.,0.,1.,1.)));
  assert(std::isnan(sp::duration(.001,.8,0.,1.,1.)));
  assert(std::isnan(sp::lengthAt(.1,.2,99.,0.,0.,1.,1.)));
  validOutput(build(straight({0.,0.,0.},{0.,-.01,-.02,-.01,0.,.01})),2);
  const auto duplicate=build(straight({0.,0.,0.},{0.,0.,-.01,-.01,-.02}));
  validOutput(duplicate,1);assert(duplicate.path.size()==3);
  failedOutput(build({}));failedOutput(build({{0.,0.,0.}}));
  failedOutput(build({{0.,0.,0.},{0.,0.,0.}}));
  failedOutput(build({{0.,0.,0.},{0.,0.,.2},{.1,0.,.2}}));
  // Late failure clears previously constructed segments too.
  failedOutput(build({{0.,0.,0.},{-.02,0.,0.},{0.,0.,0.},{0.,0.,.3}}));
  failedOutput(build({{0.,0.,0.},{nan,0.,0.}}));
  failedOutput(build({{0.,0.,0.},{.001,0.,0.}},.8));
#ifdef SEED_NATIVE_EXTRACTED
  // OFF shares the same binary. These bounded original-function cases are
  // intentional regressions, not historical whole-path replays.
  ::setenv("SEED_PARAMETERIZATION_FIX","0",1);
  {
    KinoAstar old;configure(old);
    assert(old.evaluateCurvatureWeightedDistance({0.,0.},{-.01,0.},0.,0.)==0.);
    const double t=old.evaluateDuration(.02,.05,.05);
    assert(std::abs(old.evaluateLength(t,.02,t,.05,.05)-.02)>1e-7);
  }
  ::setenv("SEED_PARAMETERIZATION_FIX","1",1);
  for(int gear:{-1,1}) {
    KinoAstar solver;configure(solver);
    solver.sample_trajs_=straight({0.,0.,0.},{0.,gear*.01,gear*.02});
    solver.start_state_<<0.,0.,0.,gear*.05;solver.end_state_<<gear*.02,0.,0.,0.;
    solver.start_ctrl_.setZero();solver.getTrajsWithTime();
    assert(solver.flat_trajs_.size()==1&&solver.shot_SList[0]==gear);
    double time=0.;for(const auto& p:solver.flat_trajs_[0].traj_pts){assert(p.allFinite()&&p[2]>0.);time+=p[2];}
    assert(std::abs(time-solver.totalTrajTime)<1e-12);
    assert((solver.evaluatePos(0.)-solver.sample_trajs_.front()).norm()<1e-12);
    assert((solver.evaluatePos(solver.totalTrajTime)-solver.sample_trajs_.back()).norm()<1e-12);
    const auto midpoint=solver.evaluatePos(.5*solver.totalTrajTime);
    assert(midpoint.allFinite()&&midpoint[0]*gear>0.&&midpoint[0]*gear<.02);
    solver.sample_trajs_={{0.,0.,0.},{0.,0.,.4}};solver.getTrajsWithTime();
    assert(solver.flat_trajs_.empty()&&solver.shot_SList.empty()&&solver.totalTrajTime==0.);
    assert(!solver.evaluatePos(0.).allFinite());
    solver.sample_trajs_=straight({0.,0.,0.},{0.,gear*.01,gear*.02});solver.getTrajsWithTime();
    assert(solver.flat_trajs_.size()==1&&solver.shot_SList[0]==gear);
    solver.start_state_[3]=-gear*.05;solver.getTrajsWithTime();
    assert(solver.flat_trajs_.empty()&&solver.totalTrajTime==0.);
  }
  {
    KinoAstar solver;configure(solver);
    solver.start_state_<<0.,0.,0.,0.;solver.end_state_<<-.0002,0.,0.,0.;solver.start_ctrl_.setZero();
    solver.sample_trajs_=straight({0.,0.,0.},{0.,-.0001,-.0002});solver.getTrajsWithTime();
    assert(solver.flat_trajs_.size()==1);
    const auto middle=solver.evaluatePos(.5*solver.totalTrajTime);
    assert(middle[0]<0.&&middle[0]>-.0002);
  }
  {
    KinoAstar solver;configure(solver);
    solver.start_state_<<0.,0.,0.,-.05;solver.end_state_<<.01,0.,0.,0.;solver.start_ctrl_.setZero();
    solver.sample_trajs_=straight({0.,0.,0.},{0.,-.01,-.02,-.01,0.,.01});solver.getTrajsWithTime();
    assert(solver.flat_trajs_.size()==2);
    assert((solver.evaluatePos(solver.shot_timeList[0])-Eigen::Vector3d(-.02,0.,0.)).norm()<1e-12);
    assert((solver.evaluatePos(solver.totalTrajTime)-Eigen::Vector3d(.01,0.,0.)).norm()<1e-12);
  }
  // Actual transformed native functions: the full PVA seed and continuously
  // sampled poses, not merely a helper distance, must be SE(2)-equivalent.
  for(int gear:{-1,1})for(double travel:{.02,2.}) {
    const auto make_solver=[&](double rotation,const Eigen::Vector2d& shift) {
      KinoAstar solver;configure(solver);
      const Eigen::Rotation2Dd r(rotation);
      const std::vector<double> fractions{0.,.25,.5,.75,1.};
      for(double f:fractions) {
        const Eigen::Vector2d p=r*Eigen::Vector2d(gear*travel*f,0.)+shift;
        solver.sample_trajs_.emplace_back(p[0],p[1],std::atan2(std::sin(rotation),std::cos(rotation)));
      }
      const auto first=solver.sample_trajs_.front(),last=solver.sample_trajs_.back();
      solver.start_state_<<first[0],first[1],first[2],gear*.05;
      solver.end_state_<<last[0],last[1],last[2],0.;solver.start_ctrl_.setZero();
      solver.getTrajsWithTime();assert(solver.flat_trajs_.size()==1);
      assert(solver.shot_SList.size()==1&&solver.shot_SList[0]==gear);
      return solver;
    };
    const auto reference=make_solver(0.,Eigen::Vector2d::Zero());
    for(double rotation:{-3.141592653589793,-3.13,-1.2,.8,3.13,3.141592653589793})
      for(const Eigen::Vector2d shift:{Eigen::Vector2d(0.,0.),Eigen::Vector2d(4.,-7.),Eigen::Vector2d(-21.,8.)}) {
        auto transformed=make_solver(rotation,shift);const Eigen::Rotation2Dd r(rotation);
        assert(std::abs(reference.totalTrajTime-transformed.totalTrajTime)<1e-9);
        assert(std::abs(reference.shot_lengthList[0]-transformed.shot_lengthList[0])<1e-11);
        const auto& rf=reference.flat_trajs_[0];const auto& tf=transformed.flat_trajs_[0];
        assert(rf.traj_pts.size()==tf.traj_pts.size());
        for(int boundary=0;boundary<2;++boundary) {
          const auto& a=boundary?rf.final_state:rf.start_state;
          const auto& b=boundary?tf.final_state:tf.start_state;
          assert((b.col(0)-(r*a.col(0)+shift)).norm()<1e-10);
          assert((b.col(1)-r*a.col(1)).norm()<1e-10);
          assert((b.col(2)-r*a.col(2)).norm()<1e-10);
        }
        for(std::size_t i=0;i<rf.traj_pts.size();++i) {
          assert((tf.traj_pts[i].head<2>()-(r*rf.traj_pts[i].head<2>()+shift)).norm()<1e-9);
          assert(std::abs(tf.traj_pts[i][2]-rf.traj_pts[i][2])<1e-9);
          assert(std::abs(sp::yawDelta(rf.thetas[i]+rotation,tf.thetas[i]))<1e-10);
        }
        auto base=reference;
        for(double fraction:{0.,.1,.25,.5,.75,.9,1.}) {
          const auto a=base.evaluatePos(fraction*base.totalTrajTime);
          const auto b=transformed.evaluatePos(fraction*transformed.totalTrajTime);
          assert((b.head<2>()-(r*a.head<2>()+shift)).norm()<1e-9);
          assert(std::abs(sp::yawDelta(a[2]+rotation,b[2]))<1e-10);
        }
      }
  }
  // A genuine curved seed crosses the -pi/+pi representation boundary. Its
  // interpolation follows the short heading increment, never a near-2pi spin.
  {
    KinoAstar curve;configure(curve);
    const double initial=3.13,turn=.04,radius=.3;
    const Eigen::Rotation2Dd r(initial);
    for(double fraction:{0.,.25,.5,.75,1.}) {
      const double angle=turn*fraction;
      const Eigen::Vector2d p=r*Eigen::Vector2d(radius*std::sin(angle),radius*(1.-std::cos(angle)));
      const double yaw=std::atan2(std::sin(initial+angle),std::cos(initial+angle));
      curve.sample_trajs_.emplace_back(p[0],p[1],yaw);
    }
    curve.start_state_<<0.,0.,initial,.05;
    const auto last=curve.sample_trajs_.back();curve.end_state_<<last[0],last[1],last[2],0.;
    curve.start_ctrl_.setZero();curve.getTrajsWithTime();assert(curve.flat_trajs_.size()==1);
    for(double fraction:{0.,.1,.25,.5,.75,.9,1.}) {
      const auto pose=curve.evaluatePos(fraction*curve.totalTrajTime);
      const double delta=sp::yawDelta(initial,pose[2]);
      assert(pose.allFinite()&&delta>=-1e-12&&delta<=turn+1e-12);
    }
    assert((curve.evaluatePos(curve.totalTrajTime)-last).norm()<1e-12);
  }
#endif
  std::cout<<"SEED_PARAMETERIZATION_PROPERTIES_PASSED (no ROS)\n";
}
